extern u16 ov74_0223CBA0[94];

int AGB_GetBoxMonAbility(GBABoxPokemon *gbaBoxMon, BoxPokemon *boxMon);

int AGB_GetBoxMonAbility(GBABoxPokemon *gbaBoxMon, BoxPokemon *boxMon) {
    int i;
    int ability;
    u16 species;
    int abilityNum;

    species = GetBoxMonData(boxMon, MON_DATA_SPECIES, NULL);
    abilityNum = AGB_GetBoxMonData(gbaBoxMon, GBA_MON_DATA_ABILITY_NUM, NULL);
    ability = GetMonBaseStat(species, SPECIES_DATA_ABILITY_2);

    if (ability != ABILITY_NONE) {
        for (i = 0; i < (NELEMS(ov74_0223CBA0)); i++) {
            if (ov74_0223CBA0[i] == species) {
                ability = GetMonBaseStat(species, SPECIES_DATA_ABILITY_1);
                break;
            }
        }

        if ((i == (NELEMS(ov74_0223CBA0))) && ((abilityNum & 1) == 0)) {
            ability = GetMonBaseStat(species, SPECIES_DATA_ABILITY_1);
        }
    } else {
        ability = GetMonBaseStat(species, SPECIES_DATA_ABILITY_1);
    }

    return ability;
}
